use std::collections::{BinaryHeap,VecDeque};impl Solution{pub fn rearrange_string(s:String,k:i32)->String{if k<=1{return s}let mut c=[0i32;26];for b in s.bytes(){c[(b-b'a')as usize]+=1}let mut h=BinaryHeap::new();for i in 0..26{if c[i]>0{h.push((c[i],i))}}let mut q=VecDeque::new();let mut o=String::new();for pos in 0..s.len(){while q.front().map(|x:&(usize,(i32,usize))|x.0<=pos).unwrap_or(false){h.push(q.pop_front().unwrap().1);}let Some((mut cnt,i))=h.pop()else{return String::new()};o.push((b'a'+i as u8)as char);cnt-=1;if cnt>0{q.push_back((pos+k as usize,(cnt,i)));}}o}}
